#!/usr/bin/env python3
"""mg_text.py — render ASCII text into an 8bpp index bitmap matching the minigame
menu sprite format (e.g. the 128x32 はじめ/じゅんい/やめる items).

The minigame UI labels are pre-rendered 8bpp bitmaps drawn as VDP1 sprites; pixel
value 0 = transparent, and the visible strokes are palette indices into CRAM at the
sprite's CMDCOLR base. To make English render in the menu's own colours we just
reuse those stroke index values. This tool draws block-letter text with a built-in
5x7 font (scaled) into a W x H index buffer and writes the raw bytes (row-major,
linear) ready to drop at a VDP1 VRAM sprite address or into a decompressed asset.

Usage:
  mg_text.py "START" out.bin --w 128 --h 32 --val 6 --hi 16 --scale 2 --x 8 --y 9
"""
import argparse

FONT = {
    'S': ["01110", "10001", "10000", "01110", "00001", "10001", "01110"],
    'T': ["11111", "00100", "00100", "00100", "00100", "00100", "00100"],
    'A': ["01110", "10001", "10001", "11111", "10001", "10001", "10001"],
    'R': ["11110", "10001", "10001", "11110", "10100", "10010", "10001"],
    'Q': ["01110", "10001", "10001", "10001", "10101", "10010", "01101"],
    'U': ["10001", "10001", "10001", "10001", "10001", "10001", "01110"],
    'I': ["11111", "00100", "00100", "00100", "00100", "00100", "11111"],
    'N': ["10001", "11001", "10101", "10101", "10011", "10001", "10001"],
    'K': ["10001", "10010", "10100", "11000", "10100", "10010", "10001"],
    'E': ["11111", "10000", "10000", "11110", "10000", "10000", "11111"],
    'X': ["10001", "10001", "01010", "00100", "01010", "10001", "10001"],
    'P': ["11110", "10001", "10001", "11110", "10000", "10000", "10000"],
    'O': ["01110", "10001", "10001", "10001", "10001", "10001", "01110"],
    'L': ["10000", "10000", "10000", "10000", "10000", "10000", "11111"],
    'Y': ["10001", "10001", "01010", "00100", "00100", "00100", "00100"],
    'G': ["01110", "10001", "10000", "10111", "10001", "10001", "01111"],
    'D': ["11110", "10001", "10001", "10001", "10001", "10001", "11110"],
    'M': ["10001", "11011", "10101", "10101", "10001", "10001", "10001"],
    'C': ["01110", "10001", "10000", "10000", "10000", "10001", "01110"],
    'B': ["11110", "10001", "10001", "11110", "10001", "10001", "11110"],
    'H': ["10001", "10001", "10001", "11111", "10001", "10001", "10001"],
    'F': ["11111", "10000", "10000", "11110", "10000", "10000", "10000"],
    'W': ["10001", "10001", "10001", "10101", "10101", "11011", "10001"],
    'V': ["10001", "10001", "10001", "10001", "10001", "01010", "00100"],
    'Z': ["11111", "00001", "00010", "00100", "01000", "10000", "11111"],
    'J': ["00111", "00010", "00010", "00010", "10010", "10010", "01100"],
    '0': ["01110", "10011", "10101", "10101", "10101", "11001", "01110"],
    '1': ["00100", "01100", "00100", "00100", "00100", "00100", "01110"],
    '2': ["01110", "10001", "00001", "00110", "01000", "10000", "11111"],
    '3': ["11110", "00001", "00001", "01110", "00001", "00001", "11110"],
    '4': ["00010", "00110", "01010", "10010", "11111", "00010", "00010"],
    '5': ["11111", "10000", "11110", "00001", "00001", "10001", "01110"],
    '6': ["00110", "01000", "10000", "11110", "10001", "10001", "01110"],
    '7': ["11111", "00001", "00010", "00100", "01000", "01000", "01000"],
    '8': ["01110", "10001", "10001", "01110", "10001", "10001", "01110"],
    '9': ["01110", "10001", "10001", "01111", "00001", "00010", "01100"],
    '-': ["00000", "00000", "00000", "11111", "00000", "00000", "00000"],
    '~': ["00000", "00000", "01001", "10101", "10010", "00000", "00000"],
    "'": ["00100", "00100", "00100", "00000", "00000", "00000", "00000"],
    '.': ["00000", "00000", "00000", "00000", "00000", "00000", "00100"],
    '!': ["00100", "00100", "00100", "00100", "00100", "00000", "00100"],
    ' ': ["00000", "00000", "00000", "00000", "00000", "00000", "00000"],
}


def render(text, W, H, val, hi, scale, x0, y0):
    buf = bytearray(W * H)
    cx = x0
    for ch in text.upper():
        g = FONT.get(ch, FONT[' '])
        for ry, row in enumerate(g):
            for rx, c in enumerate(row):
                if c == '1':
                    # top rows highlight, rest fill
                    v = hi if ry < 2 else val
                    for sy in range(scale):
                        for sx in range(scale):
                            X = cx + rx * scale + sx
                            Y = y0 + ry * scale + sy
                            if 0 <= X < W and 0 <= Y < H:
                                buf[Y * W + X] = v
        cx += (6 * scale)
    return bytes(buf)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("text")
    ap.add_argument("out")
    ap.add_argument("--w", type=int, default=128)
    ap.add_argument("--h", type=int, default=32)
    ap.add_argument("--val", type=int, default=6, help="fill palette index")
    ap.add_argument("--hi", type=int, default=16, help="highlight palette index")
    ap.add_argument("--scale", type=int, default=2)
    ap.add_argument("--x", type=int, default=8)
    ap.add_argument("--y", type=int, default=9)
    a = ap.parse_args()
    buf = render(a.text, a.w, a.h, a.val, a.hi, a.scale, a.x, a.y)
    open(a.out, "wb").write(buf)
    print(f"wrote {a.out} ({a.w}x{a.h} 8bpp, '{a.text}')")


if __name__ == "__main__":
    main()
